from collections import defaultdict, deque

def minimal_road_company_assignment(n, k, roads):
    # Build the adjacency list for the tree
    tree = defaultdict(list)
    for i, (x, y) in enumerate(roads):
        tree[x].append((y, i))
        tree[y].append((x, i))

    # Start BFS to assign companies
    # We will maintain a queue for BFS and a parent dictionary
    queue = deque([1])
    parent = {1: -1}
    company = [0] * (n - 1)
    current_company = 1
    cities_with_multiple_roads = 0

    # BFS to traverse the tree and assign companies
    while queue:
        node = queue.popleft()
        children = 0
        for neighbor, edge_index in tree[node]:
            if neighbor == parent[node]:
                continue
            children += 1
            parent[neighbor] = node
            queue.append(neighbor)

        # If the node has more than one child (more than one parent in the tree sense)
        # it can potentially be a problem city if not properly assigned.
        if children > 1:
            # Assign the first company to these edges
            for neighbor, edge_index in tree[node]:
                if neighbor == parent[node]:
                    continue
                company[edge_index] = current_company
            # Increment company for the next segment of roads
            current_company += 1

    # Check the cities that have multiple roads of the same company
    city_road_count = defaultdict(int)
    for u in range(1, n + 1):
        if len(tree[u]) > 1:  # It's a problem city if it has multiple edges
            for v, edge_index in tree[u]:
                if parent[u] != v:  # Do not count the road back to parent
                    city_road_count[company[edge_index]] += 1

    # Count number of cities with more than one road of the same company
    for count in city_road_count.values():
        if count >= 2:
            cities_with_multiple_roads += 1

    # If the number of problematic cities exceeds k, we need more companies
    while cities_with_multiple_roads > k:
        current_company += 1
        problematic_cities = set()

        # Reassign companies to avoid problematic cities
        for u in range(1, n + 1):
            if len(tree[u]) > 1:
                problematic = False
                road_count = defaultdict(int)
                for v, edge_index in tree[u]:
                    if parent[u] != v:
                        road_count[company[edge_index]] += 1
                        if road_count[company[edge_index]] >= 2:
                            problematic = True
                            break

                if problematic:
                    problematic_cities.add(u)

        # Reassign companies for problematic cities
        for u in problematic_cities:
            for v, edge_index in tree[u]:
                if parent[u] != v:
                    company[edge_index] = current_company

        # Recheck problematic cities
        city_road_count.clear()
        for u in range(1, n + 1):
            if len(tree[u]) > 1:
                for v, edge_index in tree[u]:
                    if parent[u] != v:
                        city_road_count[company[edge_index]] += 1

        cities_with_multiple_roads = 0
        for count in city_road_count.values():
            if count >= 2:
                cities_with_multiple_roads += 1

    # Output the result
    print(current_company - 1)
    print(' '.join(map(str, company)))

