def solve():
    n, k = map(int, input().split())
    graph = defaultdict(list)
    for i in range(n-1):
        x, y = map(int, input().split())
        graph[x].append((y, i))
        graph[y].append((x, i))

    companies = [0] * (n-1)
    bad_cities = set()

    def dfs(node, parent):
        child_companies = defaultdict(int)
        for child, edge in graph[node]:
            if child != parent:
                child_company = dfs(child, node)
                child_companies[child_company] += 1

        if child_companies:
            max_company = max(child_companies, key=child_companies.get)
            if child_companies[max_company] >= 2:
                bad_cities.add(node)
            companies[edge] = max_company
        else:
            companies[edge] = len(bad_cities) + 1

        return companies[edge]

    dfs(1, 0)

    if len(bad_cities) > k:
        print(-1)
    else:
        print(len(bad_cities))
        print(*companies)

